function categoryIcon(id){const n=iconNames[id]??0;return `<svg class="category-icon" viewBox="${(n%4)*384} ${Math.floor(n/4)*384} 384 384" aria-hidden="true"><image href="https://sadovod-webgl-engine-test.ddenerov.chatgpt.site/assets/market-v159/icons.webp" width="1536" height="1536"/></svg>`;}
