function subgroup(id){if(section==='decor')return PAVINGS[id]?'paving':GARDEN_PRODUCTS[id]?.subcategory||restoredTypes[id]?.subcategory||FENCES[id]?.subcategory||(FENCES[id]?'fences':'other');if(section==='structures'){if(PEN_DESIGNS[id]||id==='beehive')return 'pens';if(['wheat-mill','dairy-factory','ketchup-factory','winery'].includes(id)||restoredTypes[id]?.category==='factories')return 'factories';return restoredTypes[id]?.subcategory||'other'}if(section==='garden')return id==='vineyard'?'vineyards':bushIds.has(id)?'bushes':'trees';if(section==='machines')return id==='fuel'?'fuel':'equipment';if(section==='animals')return ['hayFeed','syrup'].includes(id)?'feed':'livestock';return '';}
